int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (!from || !to) {
        return -EINVAL;
    }

    if (tolen <= 0) {
        return -ERANGE;
    }

    while (i < fromlen && j < tolen - 1) {
        switch (from[i]) {
            case 0:
                if (j > 0) {
                    to[j++] = '.';
                }
                break;
            case 1:
                if (j > 0) {
                    to[j - 1] = '/';
                } else {
                    to[j++] = '.';
                }
                break;
            case 2:
                if (j > 0) {
                    to[j - 1] = '/'; 
                }
                if (j < tolen - 1) {
                    to[j++] = '.';
                    to[j++] = '.';
                } else {
                    return -ERANGE;
                }
                break;
            default:
                if (from[i] > 0x7f) {
                    if (j + 3 > tolen - 1) {
                        return -ERANGE;
                    }
                    to[j++] = '%';
                    to[j++] = '0' + ((from[i] >> 4) & 0x0f);
                    to[j++] = '0' + (from[i] & 0x0f);
                } else {
                    to[j++] = from[i];
                }
                break;
        }
        i++;
    }

    if (i < fromlen) {
        return -ERANGE;
    }

    to[j] = '\0';
    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen <= 0 || !to) {
        return -EINVAL;
    }

    while (i < fromlen) {
        unsigned char type = from[i];

        if (j + 1 >= tolen) {
            return -ERANGE;
        }

        if (type == 0) {
            // Current directory
            to[j++] = '.';
        } else if (type == 1) {
            // Parent directory
            if (j + 2 >= tolen) {
                return -ERANGE;
            }
            to[j++] = '.';
            to[j++] = '.';
        } else if (type == 2) {
            // Symlink
            i++;
            if (i >= fromlen) {
                return -EINVAL;
            }
            if (j + 1 >= tolen) {
                return -ERANGE;
            }
            to[j++] = from[i];
        } else {
            // Unknown type
            return -EINVAL;
        }

        i++;
    }

    to[j] = '\0';
    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j;

    if (!from || !to) {
        return -EINVAL;
    }

    if (tolen < 1) {
        return -ERANGE;
    }

    for (i = 0, j = 0; i < fromlen && j < tolen - 1; i++) {
        unsigned char c = from[i];

        if (c == 0) {
            continue;
        }

        if (c == '/') {
            if (j >= tolen - 1) {
                return -ERANGE;
            }
            to[j++] = '.';
            to[j++] = '.';
            continue;
        }

        if (c == '.') {
            if (j >= tolen - 1) {
                return -ERANGE;
            }
            to[j++] = '.';
            continue;
        }

        if (j >= tolen - 1) {
            return -ERANGE;
        }
        to[j++] = c;
    }

    to[j] = '\0';
    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (!from || !to || fromlen < 0 || tolen < 0) {
        return -EINVAL;
    }

    while (i < fromlen && j < tolen - 1) {
        unsigned char c = from[i++];

        if (c == 0) {
            break;
        } else if (c == '.') {
            if (j + 1 < tolen - 1) {
                to[j++] = '.';
                if (i < fromlen && from[i] == 0) {
                    to[j++] = '.';
                }
            } else {
                return -ERANGE;
            }
        } else if (c == '..') {
            if (j > 0) {
                j--;
                while (j >= 0 && to[j] != '/') {
                    j--;
                }
            }
            if (j < 0) {
                return -EINVAL;
            }
        } else if (c >= 'A' && c <= 'Z') {
            to[j++] = c + ('a' - 'A');
        } else if (c >= 'a' && c <= 'z') {
            to[j++] = c;
        } else if (c >= '0' && c <= '9') {
            to[j++] = c;
        } else {
            to[j++] = '_';
        }
    }

    to[j] = '\0';

    if (i < fromlen) {
        return -ERANGE;
    }

    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (!from || !to || fromlen < 0 || tolen < 0) {
        return -EINVAL;
    }

    if (tolen == 0) {
        return -ENAMETOOLONG;
    }

    while (i < fromlen) {
        unsigned char type = from[i];

        if (type == 0) {
            /* End of path components */
            break;
        }

        if (type == 1) {
            /* Current directory */
            if (j + 1 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[j++] = '.';
            to[j] = '\0';
            i += 1;
        } else if (type == 2) {
            /* Parent directory */
            if (j + 2 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[j++] = '.';
            to[j++] = '.';
            to[j] = '\0';
            i += 1;
        } else if (type == 3) {
            /* Symlink - assume it is followed by a 16-bit length of the link name */
            if (i + 2 > fromlen) {
                return -EINVAL;
            }
            int symlink_len = (from[i + 1] << 8) | from[i + 2];
            if (i + 3 + symlink_len > fromlen) {
                return -EINVAL;
            }

            if (j + symlink_len >= tolen) {
                return -ENAMETOOLONG;
            }
            for (int k = 0; k < symlink_len; k++) {
                to[j++] = from[i + 3 + k];
            }
            to[j] = '\0';
            i += 3 + symlink_len;
        } else {
            /* Unknown component type */
            return -EINVAL;
        }
    }

    return 0;
}
